parameters.jsCode:
// ===== 1. Procesamiento de la información =====
// Recibe el payload enviado por la app y lo transforma en un resumen legible.

const data = $input.item.json.data || {};
const stock = (data.stock_bajo || []).map((s) =>
  `- ${s.insumo} en ${s.ubicacion}: ${s.cantidad} uds (mínimo ${s.minimo})`
);
const mermas = (data.mermas || []).map((m) =>
  `- ${m.insumo}: ${m.cantidad} uds (${m.motivo})`
);
const minibar = (data.minibar_pendiente || []).length;

const resumen = data.resumen || {};

const textoPlano = [
  `Reporte de operación — ${data.generated_at || new Date().toISOString()}`,
  `Ítems con stock bajo/crítico: ${resumen.items_stock_bajo ?? stock.length}`,
  `Mermas registradas: ${resumen.mermas_ultimas ?? mermas.length}`,
  `Consumos de minibar pendientes de cobro: ${minibar}`,
  '',
  '=== STOCK BAJO / CRÍTICO ===',
  stock.length ? stock.join('\n') : 'Sin incidencias de stock.',
  '',
  '=== MERMAS ===',
  mermas.length ? mermas.join('\n') : 'Sin mermas registradas.',
].join('\n');

return [{ json: { ...$input.item.json, resumen_plano: textoPlano } }];

